def split(grid):
    from collections import Counter
    h,w=len(grid),len(grid[0])
    bg=Counter(v for r in grid for v in r).most_common(1)[0][0]
    for j in range(w):
        if len(Counter(r[j] for r in grid))==1 and grid[0][j]!=bg:
            return [r[:j] for r in grid],[r[j+1:] for r in grid]
    for i in range(h):
        if len(set(grid[i]))==1 and grid[i][0]!=bg:
            return grid[:i],grid[i+1:]
    raise ValueError
def transform(g):
    a,b=split(g)
    common=set(v for r in a for v in r)&set(v for r in b for v in r)
    if common: mark=sorted(common)[0]
    else:
        ca=Counter(v for r in a for v in r); cb=Counter(v for r in b for v in r)
        ba=ca.most_common(1)[0][0]; bb=cb.most_common(1)[0][0]
        sa=sum(c for k,c in ca.items() if k!=ba); sb=sum(c for k,c in cb.items() if k!=bb)
        mark=(bb if sb>=sa else ba) if sa or sb else ba
    return [[mark if x!=y else 3 for x,y in zip(ra,rb)] for ra,rb in zip(a,b)]
